React.useEffect(() => {
    let cancelled = false;
    let retryAt = Number.POSITIVE_INFINITY;
    let retryTimer: ReturnType<typeof setTimeout> | null = null;

    if (refetchNewNegatives) {
      // Invalidate first, before the peek/load loop below reads the cache, so a
      // newly-present href loads fresh instead of resolving to its stale miss.
      // buzz:// entity links resolve off the relay, not this cache — skip them.
      // Newness is judged against the live href set when supplied (so a
      // debounce-swallowed leave/re-entry still counts), else against previews.
      const seen = seenHrefsRef.current;
      const handledVersions = handledHrefVersionsRef.current;
      const liveNow = currentHrefs;
      // Preserve handled hrefs only while they remain live. A live href is not
      // marked handled until its debounced preview exists and invalidation has
      // actually been attempted; otherwise blank -> paste would consume
      // newness during the 350ms debounce and later reuse the stale negative.
      const next = new Set<string>(
        [...seen].filter((href) => liveNow.includes(href)),
      );
      const nextVersions = new Map(
        [...handledVersions].filter(([href]) => liveNow.includes(href)),
      );
      const reenteredKeys: string[] = [];
      for (const preview of previews) {
        const version = liveHrefVersions?.get(preview.href);
        const alreadyHandled =
          version === undefined
            ? seen.has(preview.href)
            : handledVersions.get(preview.href) === version;
        if (
          alreadyHandled ||
          !liveNow.includes(preview.href) ||
          preview.href.startsWith("buzz://")
        ) {
          continue;
        }
        // Drop any settled NEGATIVE from the SHARED loader cache so the load
        // below refetches instead of resolving to the stale miss. (A no-op when
        // the shared entry is healthy, in-flight, or absent.)
        metadataLoader.invalidateNegative(preview.href);
        reenteredKeys.push(metadataCacheKey(preview.href));
        next.add(preview.href);
        if (version !== undefined) nextVersions.set(preview.href, version);
      }
      seenHrefsRef.current = next;
      handledHrefVersionsRef.current = nextVersions;
      // Dropping the loader entry alone is not enough: this hook retains its own
      // resolved metadata, and the render that scheduled this effect already
      // read the stale negative from it. Clear this hook's OWN negative key for
      // every re-entered href — gating on whether the shared loader dropped a
      // settled entry misses the case where another hook left an in-flight
      // Promise in the shared cache (invalidateNegative leaves Promises alone
      // and the loop below merely coalesces onto it), which would otherwise
      // keep this hook's retained `transient_failure` as a `snapshotReady`
      // fallback the composer could turn into a sendable snapshot tag from stale
      // metadata until that fetch resolves. Clearing the local negative renders
      // the re-entered link as pending until the fresh load wins. Healthy local
      // hits are kept, so passive re-renders still show their card instantly.
      if (reenteredKeys.length > 0) {
        setResolvedMetadata((current) => {
          let changed = false;
          const nextMetadata = { ...current };
          for (const key of reenteredKeys) {
            const value = nextMetadata[key];
            if (value !== undefined && isNegativeMetadata(value)) {
              delete nextMetadata[key];
              changed = true;
            }
          }
          return changed ? nextMetadata : current;
        });
      }
    }

    const scheduleRetry = (
      { expiresAt, key }: Pick<MetadataLoadResult, "expiresAt" | "key">,
      loader: typeof metadataLoader,
    ) => {
      if (expiresAt === null || expiresAt >= retryAt) return;
      retryAt = expiresAt;
      if (retryTimer !== null) clearTimeout(retryTimer);
      retryTimer = setTimeout(
        () => {
          loader.deleteKey(key);
          setResolvedMetadata((current) => {
            if (!(key in current)) return current;
            const next = { ...current };
            delete next[key];
            return next;
          });
          setRetryGeneration(retryGeneration + 1);
        },
        Math.max(0, expiresAt - Date.now()),
      );
    };

    const cancelScheduledLoads: Array<() => void> = [];
    for (const preview of previews) {
      const loader = preview.href.startsWith("buzz://")
        ? entityMetadataLoader
        : metadataLoader;
      const cached = loader.peek(preview.href);
      if (cached !== undefined) {
        setResolvedMetadata((current) =>
          current[cached.key] === cached.metadata
            ? current
            : { ...current, [cached.key]: cached.metadata },
        );
        scheduleRetry(cached, loader);
        continue;
      }

      cancelScheduledLoads.push(
        scheduleAfterPaint(() => {
          const load = loader.load(preview.href);
          cancelScheduledLoads.push(load.cancel);
          void load.promise
            .then((result) => {
              if (cancelled) return;
              setResolvedMetadata((current) =>
                current[result.key] === result.metadata
                  ? current
                  : { ...current, [result.key]: result.metadata },
              );
              scheduleRetry(result, loader);
            })
            .catch(() => undefined);
        }),
      );
    }

    return () => {
      cancelled = true;
      for (const cancel of cancelScheduledLoads) cancel();
      if (retryTimer !== null) clearTimeout(retryTimer);
    };
  }, [previews, refetchNewNegatives, retryGeneration, newnessKey])

React.useLayoutEffect(() => {
    const previous = committedLiveHrefsRef.current;
    const active = new Set(liveCandidates);
    activeHrefsRef.current = active;
    committedLiveHrefsRef.current = active;
    committedLiveHrefVersionsRef.current = new Map(liveHrefVersions);

    for (const href of previous) {
      if (active.has(href)) continue;
      reenteringHrefsRef.current.delete(href);
      preparationGenerationRef.current.set(
        href,
        (preparationGenerationRef.current.get(href) ?? 0) + 1,
      );
    }

    if (staleReenteredHrefs.length === 0) return;
    for (const href of staleReenteredHrefs) {
      reenteringHrefsRef.current.set(href, "blocked");
      preparationGenerationRef.current.set(
        href,
        (preparationGenerationRef.current.get(href) ?? 0) + 1,
      );
      invalidateLinkPreviewPreparation(href);
    }
    const drop = new Set(staleReenteredHrefs);
    setReadyTags((current) => {
      let changed = false;
      const next = { ...current };
      for (const href of drop) {
        if (!(href in next)) continue;
        delete next[href];
        changed = true;
      }
      return changed ? next : current;
    });
  }, [liveCandidatesKey, liveHrefVersionsKey, staleReenteredKey])

React.useEffect(() => {
    const active = new Set(candidates.map((preview) => preview.href));
    setReadyTags((current) =>
      Object.fromEntries(
        Object.entries(current).filter(([href]) => active.has(href)),
      ),
    );
  }, [candidates])

React.useEffect(() => {
    for (const preview of previews) {
      const phase = reenteringHrefsRef.current.get(preview.href);
      if (phase !== undefined) {
        if (!preview.snapshotReady) {
          reenteringHrefsRef.current.set(preview.href, "refetching");
          continue;
        }
        if (phase === "blocked") continue;
        reenteringHrefsRef.current.delete(preview.href);
      }
      if (!preview.snapshotReady || readyTags[preview.href]) continue;
      const generation =
        preparationGenerationRef.current.get(preview.href) ?? 0;
      void prepareLinkPreview(preview).then((tag) => {
        if (
          !tag ||
          suppressedRef.current ||
          !activeHrefsRef.current.has(preview.href) ||
          reenteringHrefsRef.current.has(preview.href) ||
          (preparationGenerationRef.current.get(preview.href) ?? 0) !==
            generation
        ) {
          return;
        }
        readyTagsByHrefRef.current = {
          ...readyTagsByHrefRef.current,
          [preview.href]: tag,
        };
        setReadyTags((current) => ({ ...current, [preview.href]: tag }));
      });
    }
  }, [previews, readyTags])

React.useLayoutEffect(() => {
    liveCandidatesRef.current = liveCandidates;
  }, [liveCandidates])

React.useEffect(() => {
    if (liveCandidatesEmpty) setSuppressed(false);
  }, [liveCandidatesEmpty])

React.useEffect(() => {
    if (!isHomeActive || currentFeedIds.length === 0) {
      return;
    }

    void normalizedPubkey;
    markCurrentFeedSeen();
  }, [currentFeedIds, isHomeActive, normalizedPubkey])

React.useEffect(() => {
    // Persisted labels are intentionally presentation-only. Wait for a relay
    // result before seeding profile-detail caches that also carry ownership.
    if (query.dataUpdatedAt === 0) return;
    const profiles = query.data?.profiles;
    if (!profiles) return;
    for (const [pubkey, summary] of Object.entries(profiles)) {
      queryClient.setQueryData<Profile>(
        ["user-profile", pubkey],
        (existing) =>
          existing ?? {
            pubkey,
            about: null,
            // Batch endpoint gives UserProfileSummary (no event-presence flag).
            // These cached summaries are never used for the onboarding gate.
            hasProfileEvent: false,
            ...summary,
          },
      );
    }
  }, [query.data, query.dataUpdatedAt, queryClient])

React.useLayoutEffect(() => {
    onVirtualizer?.(virtualizer);
  }, [onVirtualizer, virtualizer])

React.useEffect(() => {
    const skipKeysChanged = !skipKeysEqual(prevSkipKeys.current, skipKeys);
    prevSkipKeys.current = skipKeys;
    if (skipKeysChanged || !recordsEqual(lastEmitted.current, value)) {
      lastEmitted.current = value;
      setRows(toRows(value, skipKeys));
    }
  }, [value, skipKeys])

React.useEffect(() => {
    if (modelDiscoveryKey === null || discoveryAgentCommand === null) {
      modelDiscoveryRequestRef.current += 1;
      setModelDiscoveryData(null);
      setModelDiscoveryDataKey(null);
      // When the runtime exists but is not available, surface a status message
      // so the model dropdown explains why no live models can be loaded.
      if (
        selectedRuntimeAvailability != null &&
        selectedRuntimeAvailability !== "available"
      ) {
        setModelDiscoveryStatus(
          formatModelDiscoveryErrorStatus(
            new Error(
              translateInterfaceText("Runtime not available: {value1}", {
                value1: String(selectedRuntimeAvailability),
              }),
            ),
            trimmedProvider,
            selectedRuntimeLabel,
          ),
        );
        setModelDiscoveryStatusKey(null);
      } else {
        setModelDiscoveryStatus(null);
        setModelDiscoveryStatusKey(null);
      }
      setModelDiscoveryLoading(false);
      return;
    }

    const requestId = modelDiscoveryRequestRef.current + 1;
    modelDiscoveryRequestRef.current = requestId;
    const activeAgentCommand = discoveryAgentCommand;
    const activeModelDiscoveryKey = modelDiscoveryKey;
    const cached = modelDiscoveryCacheRef.current.get(activeModelDiscoveryKey);
    if (cached) {
      setModelDiscoveryData(cached);
      setModelDiscoveryDataKey(activeModelDiscoveryKey);
      setModelDiscoveryStatus(
        synthesizeEmptyDiscoveryStatus(cached, trimmedProvider),
      );
      setModelDiscoveryStatusKey(activeModelDiscoveryKey);
      setModelDiscoveryLoading(false);
      return;
    }

    setModelDiscoveryData(null);
    setModelDiscoveryDataKey(null);
    setModelDiscoveryStatus(null);
    setModelDiscoveryStatusKey(activeModelDiscoveryKey);
    setModelDiscoveryLoading(true);
    function runModelDiscovery() {
      void discoverAgentModels({
        agentCommand: activeAgentCommand,
        agentArgs: selectedRuntimeDefaultArgs ?? [],
        provider: trimmedProvider || undefined,
        envVars,
        definitionEnv: selectedRuntimeDefinitionEnv ?? {},
      })
        .then((response) => {
          if (modelDiscoveryRequestRef.current !== requestId) {
            return;
          }
          // Only cache responses that yielded usable model options.  An
          // empty/no-switching result gets the "reopen this screen" warning,
          // and closing → reopening the dialog must re-run discovery so the
          // user's CLI-install/sign-in is actually reflected.
          if (isCacheableDiscoveryResponse(response, trimmedProvider)) {
            modelDiscoveryCacheRef.current.set(
              activeModelDiscoveryKey,
              response,
            );
          }
          setModelDiscoveryData(response);
          setModelDiscoveryDataKey(activeModelDiscoveryKey);
          setModelDiscoveryStatus(
            synthesizeEmptyDiscoveryStatus(response, trimmedProvider),
          );
          setModelDiscoveryStatusKey(activeModelDiscoveryKey);
        })
        .catch((error) => {
          if (modelDiscoveryRequestRef.current !== requestId) {
            return;
          }
          setModelDiscoveryData(null);
          setModelDiscoveryDataKey(null);
          setModelDiscoveryStatus(
            formatModelDiscoveryErrorStatus(
              error,
              trimmedProvider,
              selectedRuntimeLabel,
            ),
          );
          setModelDiscoveryStatusKey(activeModelDiscoveryKey);
        })
        .finally(() => {
          if (modelDiscoveryRequestRef.current === requestId) {
            setModelDiscoveryLoading(false);
          }
        });
    }

    if (!shouldDebounceModelDiscovery) {
      runModelDiscovery();
      return;
    }

    const timeout = window.setTimeout(
      runModelDiscovery,
      MODEL_DISCOVERY_CREDENTIAL_DEBOUNCE_MS,
    );

    return () => {
      window.clearTimeout(timeout);
      if (modelDiscoveryRequestRef.current === requestId) {
        modelDiscoveryRequestRef.current += 1;
        setModelDiscoveryLoading(false);
      }
    };
  }, [
    discoveryAgentCommand,
    envVars,
    modelDiscoveryKey,
    selectedRuntimeAvailability,
    selectedRuntimeDefaultArgs,
    selectedRuntimeDefinitionEnv,
    selectedRuntimeLabel,
    shouldDebounceModelDiscovery,
    trimmedProvider,
  ])

React.useEffect(() => {
    if (!focusKey) return;
    if (focusFiredRef.current) return;
    if (!requiredKeys.includes(focusKey)) return;

    const inputEl = requiredValueRefs.current.get(focusKey);
    if (!inputEl) return;

    focusFiredRef.current = true;

    const id = requestAnimationFrame(() => {
      inputEl.scrollIntoView({ block: "nearest" });
      inputEl.focus();
    });

    return () => cancelAnimationFrame(id);
  }, [focusKey, requiredKeys])

React.useEffect(() => {
    if (
      currentEffort !== "" &&
      !(effortValid as readonly string[]).includes(currentEffort)
    ) {
      onClear();
    }
  }, [effortValid, currentEffort])

React.useEffect(() => {
    onValidityChange?.(configIsValid);
  }, [configIsValid, onValidityChange])

React.useEffect(() => {
    if (!autoSelectModelOnProviderChange) return;
    if (!mayMutateDependentFieldsRef.current) return;
    const trimmedProvider = providerForDiscovery.trim();
    if (trimmedProvider.length === 0 || isCustomProvider) {
      autoSelectedModelScopeRef.current = null;
      return;
    }
    if ((config.model ?? "").trim().length > 0) return;
    if (modelDiscoveryLoading || discoveredModelOptions === null) return;
    const selectionScope = `${selectedRuntimeId}:${trimmedProvider}`;
    if (autoSelectedModelScopeRef.current === selectionScope) return;

    const firstModel = discoveredModelOptions.find(
      (option) => option.id.trim().length > 0,
    );
    if (!firstModel) return;

    autoSelectedModelScopeRef.current = selectionScope;
    onCustomModelEditingChange(false);
    onConfigChange({ ...config, model: firstModel.id });
  }, [
    config,
    discoveredModelOptions,
    isCustomProvider,
    modelDiscoveryLoading,
    onConfigChange,
    onCustomModelEditingChange,
    providerForDiscovery,
    selectedRuntimeId,
  ])

React.useEffect(() => {
    if (!healOnMount) return;
    const currentModel = (config.model ?? "").trim();
    if (currentModel.length === 0) return;
    if (modelDiscoveryLoading) return;

    const catalogMiss =
      discoveredModelOptions !== null &&
      !discoveredModelOptions.some(
        (option) => option.id.trim() === currentModel,
      );
    const omittedAfterSuccessfulEmpty =
      modelIsOptional && !modelControlVisible && modelDiscoverySuccessfulEmpty;
    if (!catalogMiss && !omittedAfterSuccessfulEmpty) return;

    const nextEnvVars = { ...config.env_vars };
    // Harness-native effort is model-independent; never clear it on a catalog miss.
    if (effortPersistenceKey && !isHarnessNativeEffort)
      delete nextEnvVars[effortPersistenceKey];
    onCustomModelEditingChange(false);
    onConfigChange({ ...config, env_vars: nextEnvVars, model: null });
  }, [
    config,
    discoveredModelOptions,
    modelControlVisible,
    modelDiscoveryLoading,
    modelDiscoverySuccessfulEmpty,
    modelIsOptional,
    onConfigChange,
    onCustomModelEditingChange,
    healOnMount,
    effortPersistenceKey,
    isHarnessNativeEffort,
  ])

React.useEffect(() => {
    if (!mayMutateDependentFieldsRef.current) return;
    if (!dependentFieldsDisabled) return;
    // When model is absent, harness-native effort is model-independent so no
    // orphan to fix; non-native effort with no value is already clean.
    if (
      (config.model ?? "").trim().length === 0 &&
      (isHarnessNativeEffort || currentEffortForAutoClear.length === 0)
    )
      return;

    const nextEnvVars = { ...config.env_vars };
    // Preserve harness-native effort — it is model-independent and must survive
    // the provider→Custom transition.
    if (effortPersistenceKey && !isHarnessNativeEffort)
      delete nextEnvVars[effortPersistenceKey];
    onCustomModelEditingChange(false);
    onConfigChange({ ...config, env_vars: nextEnvVars, model: null });
  }, [
    config,
    currentEffortForAutoClear,
    dependentFieldsDisabled,
    onConfigChange,
    onCustomModelEditingChange,
    effortPersistenceKey,
    isHarnessNativeEffort,
  ])

React.useEffect(() => {
    let cancelled = false;
    let unlisten: (() => void) | null = null;
    (async () => {
      try {
        const stop = await listen<InstallOutputEvent>(
          "acp-install-output",
          (event) => {
            if (cancelled) return;
            setState((current) =>
              nextInstallOutputLine(current, event.payload, runtimeId),
            );
          },
        );
        if (cancelled) {
          stop();
        } else {
          unlisten = stop;
        }
      } catch {
        // Event system unavailable (web/e2e) — the spinner shows alone.
      }
    })();
    return () => {
      cancelled = true;
      unlisten?.();
    };
  }, [runtimeId])

React.useEffect(() => {
    if (!open) return;
    setSelectedId((current) => {
      if (current === CUSTOM_ENTRY_ID) return current;
      if (current && filtered.some((e) => e.id === current)) return current;
      return filtered[0]?.id ?? null;
    });
  }, [open, filtered])

React.useEffect(() => {
    if (!isCustomColorPickerOpen || !selectedEmoji) {
      return;
    }
    const nextAvatarUrl = emojiAvatarDataUrl(selectedEmoji, customColorDraft);
    if (avatarUrl === nextAvatarUrl) {
      return;
    }
    onSelectAvatar(nextAvatarUrl);
  }, [
    avatarUrl,
    customColorDraft,
    isCustomColorPickerOpen,
    onSelectAvatar,
    selectedEmoji,
  ])

React.useEffect(() => {
    if (phase !== "review" || bitmaps.length === 0) {
      return;
    }
    const canvas = previewCanvasRef.current;
    const context = canvas?.getContext("2d");
    if (!context) {
      return;
    }

    if (!isPreviewPlaying) {
      const poster = bitmaps[Math.min(posterIndex, bitmaps.length - 1)];
      if (poster) {
        composeAvatarFrame(context, poster, composition);
      }
      return;
    }

    const previewFrames = buildPingPongAvatarFrames(bitmaps);
    let frameIndex = 0;
    let lastDrawn = 0;
    let animationFrame = 0;
    const tick = (now: number) => {
      if (now - lastDrawn >= ANIMATED_AVATAR_FRAME_DELAY_MS) {
        const bitmap = previewFrames[frameIndex];
        if (bitmap) {
          composeAvatarFrame(context, bitmap, composition);
        }
        frameIndex = (frameIndex + 1) % previewFrames.length;
        lastDrawn = now;
      }
      animationFrame = requestAnimationFrame(tick);
    };
    animationFrame = requestAnimationFrame(tick);

    return () => cancelAnimationFrame(animationFrame);
  }, [phase, bitmaps, composition, isPreviewPlaying, posterIndex])

React.useEffect(() => {
    if (phase !== "review" || bitmaps.length === 0) {
      setFilmstripFrames([]);
      return;
    }
    const handle = setTimeout(() => {
      setFilmstripFrames(buildFilmstripFrames(bitmaps, composition));
    }, 200);
    return () => clearTimeout(handle);
  }, [phase, bitmaps, composition])

React.useEffect(() => {
    if (!registerApply) {
      return;
    }
    registerApply(phase === "review" && bitmaps.length > 0 ? apply : null);
    return () => registerApply(null);
  }, [apply, bitmaps.length, phase, registerApply])

React.useEffect(() => {
    if (mode !== "emoji") return;

    let animationFrame = 0;
    let observer: MutationObserver | null = null;
    const syncSelectedEmojiButton = () => {
      const shadowRoot =
        emojiPickerContainerRef.current?.querySelector(
          "em-emoji-picker",
        )?.shadowRoot;
      if (!shadowRoot) {
        animationFrame = window.requestAnimationFrame(syncSelectedEmojiButton);
        return;
      }

      shadowRoot
        .querySelectorAll('button[data-buzz-selected="true"]')
        .forEach((button) => {
          button.removeAttribute("data-buzz-selected");
        });
      if (selectedEmoji) {
        shadowRoot.querySelectorAll(".category button").forEach((button) => {
          if (button.getAttribute("aria-label") === selectedEmoji) {
            button.setAttribute("data-buzz-selected", "true");
          }
        });
      }

      observer ??= new MutationObserver(syncSelectedEmojiButton);
      observer.observe(shadowRoot, { childList: true, subtree: true });
    };

    animationFrame = window.requestAnimationFrame(syncSelectedEmojiButton);
    return () => {
      window.cancelAnimationFrame(animationFrame);
      observer?.disconnect();
    };
  }, [mode, selectedEmoji])

React.useEffect(() => {
    if (!shouldShowColorControls) setIsCustomColorPickerOpen(false);
  }, [shouldShowColorControls])

React.useLayoutEffect(() => {
    onCustomColorPickerOpenChange?.(isAnyCustomColorPickerVisible);

    return () => {
      onCustomColorPickerOpenChange?.(false);
    };
  }, [isAnyCustomColorPickerVisible, onCustomColorPickerOpenChange])

React.useEffect(() => {
    if (!isCustomColorPickerOpen || !selectedEmoji) {
      return;
    }

    const nextAvatarUrl = emojiAvatarDataUrl(selectedEmoji, customColorDraft);
    if (avatarUrl === nextAvatarUrl) {
      return;
    }

    onUploadedAvatarChange?.(null);
    setAvatar(nextAvatarUrl);
  }, [
    avatarUrl,
    customColorDraft,
    isCustomColorPickerOpen,
    onUploadedAvatarChange,
    selectedEmoji,
    setAvatar,
  ])

React.useEffect(() => {
    if (!isAnimatedDoneQueued) return;
    setIsAnimatedDoneQueued(false);
    onDone?.();
  }, [isAnimatedDoneQueued, onDone])

React.useLayoutEffect(() => {
    onUploadingChange?.(isUploading || (!onDone && isAnimatedApplyPending));
  }, [isAnimatedApplyPending, isUploading, onDone, onUploadingChange])

React.useEffect(() => {
    for (const delivered of frames) {
      if (appliedFramesRef.current.has(delivered.frame)) continue;
      appliedFramesRef.current.add(delivered.frame);
      let grid = gridsRef.current.get(delivered.sessionId);
      if (!grid) {
        grid = new TerminalGrid(delivered.frame.viewport);
        gridsRef.current.set(delivered.sessionId, grid);
      } else if (
        grid.viewport.generation !== delivered.frame.viewport.generation ||
        grid.viewport.columns !== delivered.frame.viewport.columns ||
        grid.viewport.screenLines !== delivered.frame.viewport.screenLines
      ) {
        grid.resize(delivered.frame.viewport);
      }
      grid.apply(delivered.frame);
      consumeFrame(delivered.frame);
    }
    gridRef.current = activeSessionId
      ? (gridsRef.current.get(activeSessionId) ?? null)
      : null;
    setSelectionRows(gridRef.current?.selectionRows() ?? []);

    paintTerminal();
  }, [activeSessionId, cursorPainted, frames, terminalPalette])

React.useEffect(() => {
    if (!visible) {
      setWelcomeVisible(false);
      return;
    }
    if (!showSplash || !viewportReportingEnabled || !banner || !beginSplash())
      return;
  }, [banner, showSplash, viewportReportingEnabled, visible])

React.useEffect(() => {
    const canvas = bannerCanvasRef.current;
    if (!canvas || !banner || !terminalPalette || !welcomeVisible || !visible)
      return;
    const dpr = window.devicePixelRatio || 1;
    if (reducedMotion) {
      if (!paintTerminalBanner(canvas, banner, terminalPalette, dpr))
        setWelcomeVisible(false);
      return;
    }

    const table = buildBannerColorTable(terminalPalette);
    const start = performance.now();
    let frame = 0;
    const tick = (now: number) => {
      if (
        !paintTerminalBanner(canvas, banner, terminalPalette, dpr, {
          phase: phaseAt((now - start) / 1000),
          table,
        })
      ) {
        setWelcomeVisible(false);
        return;
      }
      frame = window.requestAnimationFrame(tick);
    };
    frame = window.requestAnimationFrame(tick);
    return () => window.cancelAnimationFrame(frame);
  }, [banner, reducedMotion, terminalPalette, visible, welcomeVisible])

React.useEffect(() => {
    setSelectedIndex((current) => {
      if (current === null || navItemCount === 0) {
        return null;
      }

      return Math.min(current, navItemCount - 1);
    });
  }, [navItemCount])

React.useEffect(() => {
    if (!navigation || !rootEventId) return;
    return navigation.register(rootEventId, attachmentKey, registeredHandler);
  }, [attachmentKey, navigation, registeredHandler, rootEventId])

React.useEffect(() => {
    const handleResize = () => setTargetBox(imageLightboxTargetBox(basisBox));
    window.addEventListener("resize", handleResize);
