() => {
    if (filter !== "repositories") return [];
    const repositories = [
      ...new Map(
        projectReadModels
          .flatMap((project) =>
            project.repositories.map((repository) => ({
              project,
              repository,
            })),
          )
          .map((item) => [item.repository.repoAddress, item]),
      ).values(),
    ];
    return repositories
      .filter(({ project, repository }) =>
        matchesProjectsSearch(searchQuery, [
          repository.name,
          repository.description,
          project.name,
        ]),
      )
      .sort((left, right) => {
        if (sort === "name") {
          return left.repository.name.localeCompare(right.repository.name);
        }
        if (sort === "created") {
          return right.repository.createdAt - left.repository.createdAt;
        }
        const leftUpdatedAt =
          repositoryActivitySummariesQuery.data?.[left.repository.repoAddress]
            ?.updatedAt ?? left.repository.createdAt;
        const rightUpdatedAt =
          repositoryActivitySummariesQuery.data?.[right.repository.repoAddress]
            ?.updatedAt ?? right.repository.createdAt;
        return rightUpdatedAt - leftUpdatedAt;
      });
  }

() => {
    const pullRequests = projectsWorkItemsQuery.data?.pullRequests.items ?? [];
    return pullRequests
      .filter(({ project, pullRequest, repository }) =>
        matchesProjectsSearch(searchQuery, [
          pullRequest.title,
          pullRequest.content,
          pullRequest.status,
          project.name,
          repository.name,
        ]),
      )
      .sort((left, right) => {
        if (sort === "name") {
          return left.pullRequest.title.localeCompare(right.pullRequest.title);
        }
        if (sort === "created") {
          return right.pullRequest.createdAt - left.pullRequest.createdAt;
        }
        return right.pullRequest.updatedAt - left.pullRequest.updatedAt;
      });
  }

() => {
    const issues = projectsWorkItemsQuery.data?.issues.items ?? [];
    return issues
      .filter(({ issue, project, repository }) =>
        matchesProjectsSearch(searchQuery, [
          issue.title,
          issue.content,
          issue.status,
          project.name,
          repository.name,
        ]),
      )
      .sort((left, right) => {
        if (sort === "name") {
          return left.issue.title.localeCompare(right.issue.title);
        }
        if (sort === "created") {
          return right.issue.createdAt - left.issue.createdAt;
        }
        return right.issue.updatedAt - left.issue.updatedAt;
      });
  }

() =>
      [...(managedAgentsQuery.data ?? [])].sort((left, right) => {
        const activeScore = (s: string) =>
          s === "running" || s === "deployed" ? 1 : 0;
        const diff = activeScore(right.status) - activeScore(left.status);
        if (diff !== 0) return diff;
        return left.name.localeCompare(right.name);
      })

() => {
    const pubkeys = new Set(
      mergeChannelKnownAgentPubkeys(
        membersQuery.data,
        managedAgentsQuery.data,
        relayAgentsQuery.data,
      ),
    );
    for (const [pubkey, profile] of Object.entries(
      dmProfilesQuery.data?.profiles ?? {},
    )) {
      if (profile.isAgent) pubkeys.add(normalizePubkey(pubkey));
    }
    return pubkeys;
  }

() => {
    const selectedMessage = messages.find((message) => message.isSelected);
    const pendingReplyMessages: InboxDisplayMessage[] = replies.map(
      (reply) => ({
        ...reply,
        depth: reply.depth ?? (selectedMessage?.depth ?? 0) + 1,
        isSelected: false,
        mentionNames: [],
      }),
    );

    if (messages.length > 0) {
      return [...messages, ...pendingReplyMessages];
    }
    if (!item) return pendingReplyMessages;

    const threadReference = getThreadReference(item.item.tags);
    return [
      {
        authorLabel: item.senderLabel,
        authorPubkey: item.item.pubkey,
        avatarUrl: item.avatarUrl,
        content: item.preview,
        createdAt: item.item.createdAt,
        depth: 0,
        fullTimestampLabel: item.fullTimestampLabel,
        id: item.id,
        isSelected: true,
        mentionNames: item.mentionNames,
        mentionPubkeysByName: item.mentionPubkeysByName,
        kind: item.item.kind,
        parentId: threadReference.parentId,
        rootId: threadReference.rootId,
        tags: item.item.tags,
        timeLabel: formatTime(item.item.createdAt),
      },
      ...pendingReplyMessages,
    ];
  }

() =>
      buildInboxListRows({
        items,
        reminders: unreadOnly
          ? []
          : reminders.filter((reminder) =>
              isDue(reminder, Math.floor(Date.now() / 1_000)),
            ),
      })

() => {
    if (!selectedChannelIdCandidate || !channels) return null;
    return (
      channels.find((channel) => channel.id === selectedChannelIdCandidate) ??
      null
    );
  }

() => {
    if (!managedChannelId || !channels) return null;
    return channels.find((channel) => channel.id === managedChannelId) ?? null;
  }

() => {
    const items = buildInboxItems({
      channels,
      currentPubkey,
      feed,
      getChannelReadAt,
      getMessageReadAt,
      getThreadReadAt,
      profiles: feedProfiles,
    });
    return filterInboxItems(items);
  }

() => {
    return inboxItems.filter(
      (item) =>
        matchesInboxFilter(item, filter, ownedAgentPubkeys) &&
        (!unreadOnly ||
          !effectiveDoneSet.has(item.id) ||
          item.conversationId === selectedConversationId),
    );
  }

() => {
    const normalizedQuery = query.trim().toLowerCase();
    if (!normalizedQuery) return files;
    return files.filter((file) =>
      file.path.toLowerCase().includes(normalizedQuery),
    );
  }

() =>
      (workItemsQuery.data?.issues.items ?? []).map(
        ({ issue, repository: issueRepository }) => ({
          issue,
          project: issueRepository,
        }),
      )

() => {
    if (tab === "issues" && selectedIssueId) {
      return {
        backLabel: "Back to Tasks",
        navigation: {
          issueId: selectedIssueId,
          repositoryId: selectedIssueItem?.project.id,
        },
        onBack: () => setSelectedIssueId(null),
      };
    }
    if (tab === "prs" && selectedPullRequestId) {
      return {
        backLabel: "Back to Reviews",
        navigation: { pullRequestId: selectedPullRequestId },
        onBack: () => setSelectedPullRequestId(null),
      };
    }
    if (tab === "commits" && selectedCommitHash) {
      return {
        backLabel: "Back to Commits",
        navigation: {
          commitHash: selectedCommitHash,
          repositoryId: selectedCommitRepository.id,
        },
        onBack: () => {
          setSelectedCommitHash(null);
          setSelectedCommitRepositoryId(null);
        },
      };
    }
    if (tab === "files" && filesContext?.onBack) {
      return {
        backLabel: "Back to Files",
        navigation: { filePath: filesContext.path },
        onBack: filesContext.onBack,
      };
    }
    return null;
  }

() => {
    const workingSet = new Set(
      workingBotPubkeys.map((pubkey) => pubkey.toLowerCase()),
    );

    return agents.filter((agent) => workingSet.has(agent.pubkey.toLowerCase()));
  }

() => {
    if (!singleWorkingAgent) {
      return [];
    }

    const seen = new Set<string>();
    const headlines: string[] = [];
    const scopedTranscript = channelId
      ? transcript.filter((item) => item.channelId === channelId)
      : transcript;

    // Two-tier scan: spine items first (reads recede when real work is present).
    // If no spine headlines are found (session start / idle), fall back to all
    // meaningful items so the bar isn't left empty.
    const passFilter: (item: (typeof scopedTranscript)[number]) => boolean =
      scopedTranscript.some(isSpineItem) ? isSpineItem : isMeaningfulItem;

    for (let i = scopedTranscript.length - 1; i >= 0; i--) {
      const item = scopedTranscript[i];
      if (!passFilter(item)) {
        continue;
      }
      const headline = getActivityHeadline(item);
      if (!headline || seen.has(headline)) {
        continue;
      }

      seen.add(headline);
      headlines.unshift(headline);
      if (headlines.length >= 5) {
        break;
      }
    }

    return headlines;
  }

() => {
    const pubkeys = new Set<string>();
    const addMentionPubkeys = (tags?: string[][]) => {
      for (const tag of tags ?? []) {
        const pubkey = getMentionTagPubkey(tag);
        if (pubkey) {
          pubkeys.add(pubkey);
        }
      }
    };
    for (const post of posts) {
      pubkeys.add(post.pubkey);
      addMentionPubkeys(post.tags);
      if (post.threadSummary?.participants) {
        for (const pk of post.threadSummary.participants) {
          pubkeys.add(pk);
        }
      }
    }
    if (threadQuery.data) {
      pubkeys.add(threadQuery.data.post.pubkey);
      addMentionPubkeys(threadQuery.data.post.tags);
      for (const reply of threadQuery.data.replies) {
        pubkeys.add(reply.pubkey);
        addMentionPubkeys(reply.tags);
      }
    }
    return [...pubkeys];
  }

() => {
    if (repositoryId) return repositoryId;
    const kindStr = `${String(KIND_REPO_ANNOUNCEMENT)}:`;
    if (!projectId.startsWith(kindStr)) return undefined;
    return projectId.slice(kindStr.length);
  }

() => {
    const channelId = repository?.channelId ?? project?.projectChannelId;
    if (!channelId) return null;
    return {
      channelId,
      channelName: repository?.name ?? project?.name ?? "Project",
    };
  }

() => {
    if (!showRecipientPicker || visibleSearchResults.length === 0) {
      return -1;
    }

    if (highlightedRecipientPubkey === null) {
      return 0;
    }

    return visibleSearchResults.findIndex(
      (user) => user.pubkey === highlightedRecipientPubkey,
    );
  }

() => {
    if (!agent) return {};
    const profiles: UserProfileLookup = {
      [normalizePubkey(agent.pubkey)]: {
        avatarUrl: agent.avatarUrl,
        displayName: agent.name,
        isAgent: true,
        name: agent.name,
        nip05Handle: null,
        ownerPubkey: null,
      },
    };
    if (currentPubkey) {
      profiles[normalizePubkey(currentPubkey)] = {
        avatarUrl: currentProfile?.avatarUrl ?? null,
        displayName: "You",
        isAgent: false,
        name: null,
        nip05Handle: currentProfile?.nip05Handle ?? null,
        ownerPubkey: null,
      };
    }
    return profiles;
  }

() => {
    if (!conversationChannel) return [];
    return formatTimelineMessages(
      conversationQuery.data ?? [],
      conversationChannel,
      currentPubkey,
      currentProfile?.avatarUrl ?? null,
      conversationProfiles,
    )
      .filter(
        (message) =>
          (message.kind === KIND_STREAM_MESSAGE ||
            message.kind === KIND_STREAM_MESSAGE_V2) &&
          !message.parentId,
      )
      .map((message) => {
        if (!contextEnvelope || !message.body.startsWith(contextEnvelope)) {
          return message;
        }
        return {
          ...message,
          body: message.body.slice(contextEnvelope.length).trim(),
        };
      })
      .filter((message) => message.body.length > 0);
  }

() => {
    if (!sessionBoundary) return [];
    return allConversationMessages
      .filter(
        (message) =>
          message.createdAt >= sessionBoundary.firstMessageCreatedAt &&
          !sessionBoundary.baselineMessageIds.has(message.id),
      )
      .slice(-12);
  }
